/**
 * Admin withdrawal queue component
 *
 * Shows deposits that are ready for withdrawal (privacy period elapsed).
 * Includes buttons to process individual or all withdrawals.
 * Requires system admin privileges.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useAdminDeposits } from '../../../hooks/useAdminDeposits';
import type {
  AdminDepositItem,
  AdminDepositListResponse,
  ProcessWithdrawalResponse,
  ProcessAllWithdrawalsResponse,
} from '../../../types/deposit';
import { FeatureDisabledMessage } from './FeatureDisabledMessage';
import { isFeatureDisabledError } from './featureDisabled';
import { EarlyWithdrawalModal, WithdrawalRow } from './AdminWithdrawalQueueParts';
import { isWithinPrivacyPeriod } from './AdminWithdrawalQueueHelpers';

type QueueSortField = 'userId' | 'amountLamports' | 'withdrawalAvailableAt';
type SortOrder = 'asc' | 'desc';

export interface AdminWithdrawalQueueProps {
  /** Number of items per page (default: 20) */
  pageSize?: number;
  /** Auto-refresh interval in milliseconds (0 to disable) */
  refreshInterval?: number;
  /** External refresh signal from parent coordinator */
  refreshSignal?: number;
  /** Additional CSS classes */
  className?: string;
  /** Callback when list is loaded */
  onLoad?: (response: AdminDepositListResponse) => void;
  /** Callback when a withdrawal item is clicked */
  onItemClick?: (item: AdminDepositItem) => void;
  /** Callback when a withdrawal is processed */
  onWithdrawalProcessed?: (response: ProcessWithdrawalResponse) => void;
  /** Callback when all withdrawals are processed */
  onAllProcessed?: (response: ProcessAllWithdrawalsResponse) => void;
}

/**
 * Admin withdrawal queue display
 *
 * Shows deposits ready for withdrawal processing with action buttons.
 */
export function AdminWithdrawalQueue({
  pageSize = 20,
  refreshInterval = 0,
  refreshSignal,
  className = '',
  onLoad,
  onItemClick,
  onWithdrawalProcessed,
  onAllProcessed,
}: AdminWithdrawalQueueProps) {
  const {
    listPendingWithdrawals,
    processWithdrawal,
    processAllWithdrawals,
    isLoading,
    error,
    clearError,
  } = useAdminDeposits();

  const [items, setItems] = useState<AdminDepositItem[]>([]);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<QueueSortField>('withdrawalAvailableAt');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const toggleSort = (field: QueueSortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder(field === 'withdrawalAvailableAt' ? 'asc' : 'desc');
    }
  };

  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => {
      let aVal: string | number;
      let bVal: string | number;

      switch (sortField) {
        case 'userId':
          aVal = a.userId.toLowerCase();
          bVal = b.userId.toLowerCase();
          break;
        case 'amountLamports':
          aVal = a.amountLamports ?? 0;
          bVal = b.amountLamports ?? 0;
          break;
        case 'withdrawalAvailableAt':
          aVal = a.withdrawalAvailableAt ? new Date(a.withdrawalAvailableAt).getTime() : 0;
          bVal = b.withdrawalAvailableAt ? new Date(b.withdrawalAvailableAt).getTime() : 0;
          break;
        default:
          return 0;
      }

      if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, sortField, sortOrder]);

  // Processing state
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [processingAll, setProcessingAll] = useState(false);
  const [processResult, setProcessResult] = useState<{
    type: 'success' | 'error';
    message: string;
  } | null>(null);

  // Early withdrawal confirmation modal
  const [earlyWithdrawalItem, setEarlyWithdrawalItem] = useState<AdminDepositItem | null>(null);

  const fetchItems = useCallback(async () => {
    try {
      const result = await listPendingWithdrawals({ limit: pageSize, offset });
      setItems(result.deposits);
      setTotal(result.total);
      onLoad?.(result);
      setLoadError(null);
    } catch (err) {
      const message =
        err && typeof err === 'object' && 'message' in err
          ? String((err as { message: unknown }).message)
          : 'Failed to load pending withdrawals';
      setLoadError(message);
    }
  }, [pageSize, offset, listPendingWithdrawals, onLoad]);

  // Reset offset when page size changes
  useEffect(() => {
    setOffset(0);
  }, [pageSize]);

  // Fetch on mount and when dependencies change
  useEffect(() => {
    fetchItems();
  }, [fetchItems]);

  useEffect(() => {
    if (refreshSignal === undefined) return;
    fetchItems();
  }, [refreshSignal, fetchItems]);

  // Auto-refresh
  useEffect(() => {
    if (refreshSignal !== undefined) return;
    if (refreshInterval <= 0) return;

    const interval = setInterval(fetchItems, refreshInterval);
    return () => clearInterval(interval);
  }, [refreshInterval, refreshSignal, fetchItems]);

  // Clear result message after 5 seconds
  useEffect(() => {
    if (!processResult) return;
    const timer = setTimeout(() => setProcessResult(null), 5000);
    return () => clearTimeout(timer);
  }, [processResult]);

  const totalPages = Math.ceil(total / pageSize);
  const currentPage = Math.floor(offset / pageSize) + 1;

  const goToPage = (page: number) => {
    const newOffset = (page - 1) * pageSize;
    setOffset(Math.max(0, Math.min(newOffset, Math.max(0, total - 1))));
  };

  const handleProcessSingle = async (item: AdminDepositItem, force = false) => {
    // Check if within privacy period and not forcing
    if (!force && isWithinPrivacyPeriod(item.withdrawalAvailableAt)) {
      setEarlyWithdrawalItem(item);
      return;
    }

    setProcessingId(item.id);
    setProcessResult(null);

    try {
      const result = await processWithdrawal(item.id, { force });
      if (result.success) {
        setProcessResult({
          type: 'success',
          message: `Withdrawal processed: ${result.txSignature?.slice(0, 12)}...`,
        });
        onWithdrawalProcessed?.(result);
        await fetchItems();
      } else {
        setProcessResult({
          type: 'error',
          message: result.error || 'Failed to process withdrawal',
        });
      }
    } catch (err) {
      setProcessResult({
        type: 'error',
        message: err instanceof Error ? err.message : 'Failed to process withdrawal',
      });
    } finally {
      setProcessingId(null);
      setEarlyWithdrawalItem(null);
    }
  };

  const handleProcessAll = async () => {
    if (items.length === 0) return;

    setProcessingAll(true);
    setProcessResult(null);

    try {
      const result = await processAllWithdrawals();
      if (result.totalSucceeded > 0) {
        setProcessResult({
          type: 'success',
          message: `Processed ${result.totalSucceeded}/${result.totalProcessed} withdrawals`,
        });
      } else if (result.totalFailed > 0) {
        setProcessResult({
          type: 'error',
          message: `Failed to process ${result.totalFailed} withdrawals`,
        });
      }
      onAllProcessed?.(result);
      await fetchItems();
    } catch (err) {
      setProcessResult({
        type: 'error',
        message: err instanceof Error ? err.message : 'Failed to process withdrawals',
      });
    } finally {
      setProcessingAll(false);
    }
  };

  // Feature disabled state
  const errorMessage = loadError || error;
  if (isFeatureDisabledError(errorMessage)) {
    return <FeatureDisabledMessage feature="Privacy Cash" className={className} />;
  }

  // Error state
  if (errorMessage) {
    return (
      <div
        className={`cedros-admin-withdrawal-queue cedros-admin-withdrawal-queue-error ${className}`}
      >
        <p className="cedros-admin-error">{errorMessage}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline"
          onClick={() => {
            clearError();
            setLoadError(null);
            fetchItems();
          }}
        >
          Retry
        </button>
      </div>
    );
  }

  // Loading state (initial load only)
  if (isLoading && items.length === 0 && !processingId && !processingAll) {
    return (
      <div
        className={`cedros-admin-withdrawal-queue cedros-admin-withdrawal-queue-loading ${className}`}
      >
        <span className="cedros-admin-loading-indicator" />
        <span className="cedros-admin-loading-text">Loading withdrawal queue...</span>
      </div>
    );
  }

  return (
    <div className={`cedros-admin-withdrawal-queue ${className}`}>
      {earlyWithdrawalItem && (
        <EarlyWithdrawalModal
          item={earlyWithdrawalItem}
          processingId={processingId}
          onConfirm={handleProcessSingle}
          onCancel={() => setEarlyWithdrawalItem(null)}
        />
      )}

      {processResult && (
        <div
          className={`cedros-admin-result cedros-admin-result-${processResult.type}`}
          role="status"
          aria-live="polite"
        >
          {processResult.message}
        </div>
      )}

      <div className="cedros-admin-withdrawal-queue-header">
        <h4 className="cedros-admin-withdrawal-queue-title">Pending Withdrawals</h4>
        <div className="cedros-admin-withdrawal-queue-actions">
          <span className="cedros-admin-queue-count">{total} pending</span>
          <button
            type="button"
            className="cedros-admin__stats-bar-refresh"
            onClick={fetchItems}
            disabled={isLoading || processingAll}
            title="Refresh queue"
            aria-label="Refresh queue"
          >
            {isLoading && !processingAll ? '...' : '↻'}
          </button>
          <button
            type="button"
            className="cedros-button cedros-button-primary cedros-button-sm"
            onClick={handleProcessAll}
            disabled={isLoading || processingAll || items.length === 0}
            title="Process all ready withdrawals"
          >
            {processingAll ? 'Processing...' : 'Process All'}
          </button>
        </div>
      </div>

      {items.length === 0 ? (
        <div className="cedros-admin-empty">
          <p className="cedros-admin-empty-message">No pending withdrawals.</p>
        </div>
      ) : (
        <>
          <div className="cedros-admin-withdrawal-table">
            <div className="cedros-admin-withdrawal-thead">
              <div className="cedros-admin-withdrawal-th">
                <button
                  type="button"
                  className={`cedros-admin-sort-button ${sortField === 'userId' ? 'cedros-admin-sort-active' : ''}`}
                  onClick={() => toggleSort('userId')}
                  aria-label="Sort by user"
                >
                  User{' '}
                  <span className="cedros-admin-sort-icon">
                    {sortField === 'userId' ? (sortOrder === 'asc' ? '↑' : '↓') : '↕'}
                  </span>
                </button>
              </div>
              <div className="cedros-admin-withdrawal-th">
                <button
                  type="button"
                  className={`cedros-admin-sort-button ${sortField === 'amountLamports' ? 'cedros-admin-sort-active' : ''}`}
                  onClick={() => toggleSort('amountLamports')}
                  aria-label="Sort by amount"
                >
                  Amount{' '}
                  <span className="cedros-admin-sort-icon">
                    {sortField === 'amountLamports' ? (sortOrder === 'asc' ? '↑' : '↓') : '↕'}
                  </span>
                </button>
              </div>
              <div className="cedros-admin-withdrawal-th">
                <button
                  type="button"
                  className={`cedros-admin-sort-button ${sortField === 'withdrawalAvailableAt' ? 'cedros-admin-sort-active' : ''}`}
                  onClick={() => toggleSort('withdrawalAvailableAt')}
                  aria-label="Sort by ready since"
                >
                  Ready Since{' '}
                  <span className="cedros-admin-sort-icon">
                    {sortField === 'withdrawalAvailableAt'
                      ? sortOrder === 'asc'
                        ? '↑'
                        : '↓'
                      : '↕'}
                  </span>
                </button>
              </div>
              <div className="cedros-admin-withdrawal-th">Waiting</div>
              <div className="cedros-admin-withdrawal-th cedros-admin-withdrawal-th-action">
                Action
              </div>
            </div>
            {sortedItems.map((item) => (
              <WithdrawalRow
                key={item.id}
                item={item}
                processingId={processingId}
                processingAll={processingAll}
                onItemClick={onItemClick}
                onProcess={handleProcessSingle}
              />
            ))}
          </div>

          {totalPages > 1 && (
            <div className="cedros-admin-pagination">
              <button
                type="button"
                className="cedros-button cedros-button-outline cedros-button-sm"
                onClick={() => goToPage(currentPage - 1)}
                disabled={currentPage <= 1}
              >
                Previous
              </button>
              <span className="cedros-admin-page-info">
                Page {currentPage} of {totalPages} ({total} total)
              </span>
              <button
                type="button"
                className="cedros-button cedros-button-outline cedros-button-sm"
                onClick={() => goToPage(currentPage + 1)}
                disabled={currentPage >= totalPages}
              >
                Next
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
